#include <Arduino.h>

// Пин встроенного RGB-светодиода (WS2812)
// Для ESP32-S3-DevKitC-1 v1.1 обычно 48. Если не работает — попробуйте 38.
#define RGB_PIN 48

String inputString = "";

void setup() {
  Serial.begin(115200);
  delay(1000); // Небольшая задержка для инициализации USB

  Serial.println("Введите цвет в формате RRGGBB (например, 00ff00):");

  // Выключаем светодиод при старте
  neopixelWrite(RGB_PIN, 0, 0, 0);
}

void loop() {
  while (Serial.available()) {
    char c = Serial.read();

    if (c == '\n' || c == '\r') {
      if (inputString.length() >= 6) {
        processColor(inputString);
      }
      inputString = ""; // Очищаем буфер после обработки
    } else {
      inputString += c;
    }
  }
}

void processColor(String hex) {
  hex.trim(); // Убираем пробелы и лишние символы

  if (hex.length() != 6) {
    Serial.println("Ошибка: нужно ровно 6 hex-символов (RRGGBB)");
    return;
  }

  // Преобразуем HEX-строку в число
  long number = strtol(hex.c_str(), NULL, 16);

  // Извлекаем компоненты
  uint8_t r = (number >> 16) & 0xFF;
  uint8_t g = (number >> 8) & 0xFF;
  uint8_t b = number & 0xFF;

  // Устанавливаем цвет
  neopixelWrite(RGB_PIN, r, g, b);

  Serial.printf("Установлен цвет: R=%d G=%d B=%d\n", r, g, b);
}
